/*
 * Genesis Render - Metal backend (public entry point)
 *
 * The Metal RHI is implemented entirely in metal_backend.mm (Objective-C++,
 * ARC).  This header deliberately exposes nothing but the factory so that no
 * renderer / demo translation unit ever needs Objective-C or Metal headers.
 *
 * Resource slot convention (shared with the MSL generated by SPIRV-Cross, see
 * shaders/common/genesis_shader.h):
 *   [[buffer(set * 8 + binding)]]   uniform blocks
 *   [[texture(set * 8 + binding)]]  textures, with the sampler in the same slot
 *   [[buffer(24)]]                  push constants (setVertexBytes)
 *   [[buffer(30)]]                  the vertex stream
 */
#ifndef __GENESIS_METAL_BACKEND_HPP__
#define __GENESIS_METAL_BACKEND_HPP__

#include "rhi/rhi.hpp"

namespace Genesis
{
    namespace RHI
    {
        static constexpr uint32_t kMetalFramesInFlight = 2;
        static constexpr uint32_t kMetalPushConstantSlot = 24;
        static constexpr uint32_t kMetalVertexBufferSlot = 30;

        // Creates an uninitialised Metal device; call initialize() on it.
        RHIDevice *createMetalDevice();
    } // namespace RHI
} // namespace Genesis

#endif /* __GENESIS_METAL_BACKEND_HPP__ */
